<?php require_once 'includes/auth.php';require_login();verify_csrf();$name=trim($_POST['name']??'');if(strlen($name)<2)redirect('profile.php?error=Invalid+name');$s=mysqli_prepare($conn,"UPDATE users SET name=? WHERE id=?");$id=user()['id'];mysqli_stmt_bind_param($s,'si',$name,$id);mysqli_stmt_execute($s);$_SESSION['user']['name']=$name;log_activity('updated','profile','Updated profile');redirect('profile.php?msg=Profile+updated');
